beforeExample:
import java.lang.StringBuffer;

class Example {
    void foo() {
        StringBuffer buffer = new StringBuffer();
        System.out.println(buffer.toString());
    }
    void bar(String s) {
        StringBuffer anotherBuffer = new StringBuffer(s);
        System.out.println(anotherBuffer.toString());
    }
}

afterExample:
import java.lang.StringBuilder;

class Example {
    void foo() {
        StringBuilder buffer = new StringBuilder();
        System.out.println(buffer.toString());
    }
    void bar(String s) {
        StringBuilder anotherBuffer = new StringBuilder(s);
        System.out.println(anotherBuffer.toString());
    }
}

negativeExample:
import java.lang.StringBuffer;

class Example {
    StringBuffer sharedBuffer = new StringBuffer(); // This is a field, not a local variable
    void foo() {
        System.out.println(sharedBuffer.toString());
    }
}
